 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # classify separator orientation and repeat border-adjacent color data
    vcol=max(range(w),key=lambda c:sum(g[r][c]==5 for r in range(h)))
    if sum(g[r][vcol]==5 for r in range(h)) >= max(sum(x==5 for x in row) for row in g):
        # vertical frame: vertical row markers on left expand horizontally
        # where present; right-side sample stripes are reproduced upward.
        source=[r for r in range(h) if any(g[r][c] not in (0,5) for c in range(vcol+1,w))]
        if source:
            pattern=[g[r][vcol+1:] for r in source]
            top=min(source)
            for r in range(1,top):
                g[r][vcol+1:]=pattern[(top-r-1)%len(pattern)]
        for r in range(h):
            labels=[g[r][c] for c in range(vcol) if g[r][c] not in (0,5)]
            if labels:
                for c in range(1,vcol):
                    if g[r][c]==0:g[r][c]=labels[-1]
        return g
    # horizontal frame: repeat rows encoded beneath the frame
    frame=max(range(h),key=lambda r:sum(x==5 for x in g[r]))
    left=min(c for c,x in enumerate(g[frame]) if x==5)
    right=max(c for c,x in enumerate(g[frame]) if x==5)
    samples=[r for r in range(frame+1,h) if any(g[r][c] not in (0,5) for c in range(left+1,right))]
    if samples:
        pat=[g[r][left+1:right] for r in samples]
        for r in range(frame+1,min(samples)):
