    # A perpendicular color-key column expands across the opposite chamber.
    key=right+1
    if key<w:
        for r in range(frame+1,h):
            color=g[r][key]
            if color not in (0,5):
                for c in range(key+1,w):
                    if g[r][c]==0:g[r][c]=color
    return g
